a = [int(x) for x in open('17.txt')]
k = 0
for i in range(len(a) - 1):
    if a[i] % 2 == a[i + 1] % 2:
        k += 1
print(k)

a = [int(x) for x in open('17.txt')]
k, mx = 0, None
for i in range(len(a) - 1):
    x, y = a[i], a[i + 1]
    if x > 0 and y > 0 and (x + y) % 7 == 0:
        k += 1
        if mx is None or x * y > mx:
            mx = x * y
print(k, mx)

a = [int(x) for x in open('17.txt')]
M = min(x for x in a if 100 <= abs(x) <= 999 and abs(x) % 10 == 5)

def f(x):
    return 100 <= abs(x) <= 999

s = []
for i in range(len(a) - 1):
    x1, x2 = a[i], a[i + 1]
    if f(x1) + f(x2) >= 1 and (x1 + x2) % M == 0:
        s.append(x1 + x2)
print(len(s), max(s))

a = [int(x) for x in open('17.txt')]
M = max(x for x in a if abs(x) % 100 == 13)

def f(x):
    return 100 <= abs(x) <= 999

s = []
for i in range(len(a) - 2):
    x1, x2, x3 = a[i], a[i + 1], a[i + 2]
    if f(x1) + f(x2) + f(x3) == 2 and x1 + x2 + x3 <= M:
        s.append(x1 + x2 + x3)
print(len(s), max(s))

a = [int(x) for x in open('17.txt')]
M = min(x for x in a if 100 <= abs(x) <= 999 and abs(x) % 100 == 15)
p = []
for i in range(len(a) - 2):
    t = a[i:i + 3]
    if all(x > 0 for x in t) or all(x < 0 for x in t):
        v = max(t) * min(t)
        if v > M ** 2:
            p.append(v)
print(len(p), min(p))

a = [int(x) for x in open('17.txt')]

def ds(x):
    return sum(int(c) for c in str(abs(x)))

s = [a[i] + a[i + 1] for i in range(len(a) - 1)
     if ds(a[i]) > ds(a[i + 1]) and a[i] % 2 != 0 and a[i + 1] % 2 != 0]
print(len(s), min(s))

a = [int(x) for x in open('17.txt')]
A = sum(a) / len(a)
k, best, pos = 0, None, None
for i in range(len(a) - 2):
    t = a[i:i + 3]
    if sum(1 for x in t if x > A) == 2 and 10000 <= abs(sum(t)) <= 99999:
        k += 1
        if best is None or sum(t) > best:
            best, pos = sum(t), i + 1
print(k, pos)
